Code.Terraform:
```hcl
# SageMaker AI training job whose output artifacts are KMS encrypted
resource "aws_sagemaker_training_job" "<example_resource_name>" {
  training_job_name = "<example_resource_name>"
  role_arn          = "<example_role_arn>"

  algorithm_specification {
    training_image      = "<example_ecr_image_uri>"
    training_input_mode = "File"
  }

  output_data_config {
    s3_output_path = "s3://<example_bucket>/output/"
    kms_key_id     = "<example_kms_key_arn>" # CRITICAL: encrypts the model artifacts written to S3
  }

  resource_config {
    instance_type     = "ml.m5.large"
    instance_count    = 1
    volume_size_in_gb = 30
  }

  stopping_condition {
    max_runtime_in_seconds = 3600
  }
}
```
